  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "The **20% general warranty cap (AUD 4.8m)** is a commercial negotiating point, not automatically unacceptable."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "For general warranties, seek a longer notification window, lower thresholds and a **tipping basket** rather than recovery only above AUD 250,000."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "For general warranties, seek a longer notification window"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Seek separate fundamental warranties, a cap at least equal to the purchase price and materially longer survival."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Any restriction on liability for Seller fraud or fraudulent concealment, or exclusion of rights that cannot lawfully be excluded."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket disclosure of public registers and material merely referred to in other documents."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Prefer deletion of the knowledge exclusion."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "A Buyer-waivable condition precedent for effective written consent, with all relevant conditions satisfied."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "A release promised after Completion is inadequate for a debt-free/cash-free acquisition."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Express Seller funding or a purchase-price deduction/debt-like treatment, without duplication elsewhere."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "A broader specific indemnity covering losses from defective ownership, missing rights and associated third-party claims—not merely the outstanding invoice."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A specific indemnity for resulting pre-Completion incident liabilities and reasonable response costs, subject to legally permissible recovery."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "Allocate it consistently under working-capital, debt-like or transaction-cost definitions."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Confine each limitation to its expressly identified claim category."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 supports the Seller’s registered holding but does not independently establish unencumbered title or exclude competing rights."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek a dedicated pre-Completion tax indemnity with an appropriate longer claim period, and tailored IP protection."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

